5.2 Activity 2: a page of tasks


src/main/kotlin/utils/Pagination.kt

package utils

/**
 * One page of a list. Pages are numbered from 1. [paginate] clamps the requested page
 * into range, so a page number that no longer exists shows the last page rather than
 * an error.
 */
data class Page&lt;T&gt;(
    val items: List&lt;T&gt;,
    val currentPage: Int,
    val totalPages: Int,
    val totalItems: Int,
) {
    fun toPebbleContext(): Map&lt;String, Any&gt; =
        mapOf(
            "items" to items,
            "currentPage" to currentPage,
            "totalPages" to totalPages,
            "totalItems" to totalItems,
        )

    companion object {
        const val DEFAULT_SIZE = 10

        fun &lt;T&gt; paginate(items: List&lt;T&gt;, requestedPage: Int, pageSize: Int = DEFAULT_SIZE): Page&lt;T&gt; {
            require(pageSize &gt; 0) { "pageSize must be positive" }
            val totalPages = maxOf(1, (items.size + pageSize - 1) / pageSize)
            val current = requestedPage.coerceIn(1, totalPages)
            val from = (current - 1) * pageSize
            val to = minOf(from + pageSize, items.size)
            val pageItems = if (from &lt; items.size) items.subList(from, to) else emptyList()
            return Page(pageItems, current, totalPages, items.size)
        }
    }
}

Page&lt;T&gt; is one page of any list. paginate clamps the requested number into range, so a page number that no longer exists, because the tasks on it were deleted, shows the last page rather than an error. toPebbleContext is the shape templates see; the page size lives in one constant and no template states it.
listTasks is now one route with two answers.


